#include <P1AM.h>
bool latch = false;
void setup() {
  while (!P1.init()) { }
}
void loop() {
  bool lowFloat = P1.readDiscrete(1, 1);
  bool highFloat = P1.readDiscrete(1, 2);
  bool hand = P1.readDiscrete(1, 3);
  bool autoSel = P1.readDiscrete(1, 4);
  if (lowFloat) latch = true;
  if (highFloat) latch = false;
  if (hand) {
    P1.writeDiscrete(true, 2, 1);
  } else if (autoSel) {
    P1.writeDiscrete(latch, 2, 1);
  } else {
    P1.writeDiscrete(false, 2, 1);
  }
}

